INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('ielts-5-0','IELTS','Mục tiêu 5.0','Hướng tới IELTS Listening 5.0','Nghe chép chính tả hỗ trợ mục tiêu học; không phải thi thử hay điểm dự đoán.','Cần audio và transcript đã kiểm tra: thông tin cụ thể, dịch vụ, học tập và diễn giải học thuật; độ dài, từ vựng, nối âm, tốc độ tự nhiên và mật độ thông tin phải phù hợp mục tiêu. Không suy từ CEFR.','Đang bổ sung nội dung. Chưa có đủ bài đã kiểm tra để mở khóa theo mốc điểm này.',2,TRUE,FALSE);
