INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('ielts-foundation','IELTS','Nền tảng','Chuẩn bị kỹ năng nghe cho IELTS Listening','Chọn nhóm bài rồi nghe và chép lại từng câu. Một bài dùng chung lịch sử ở mọi khóa.','Xếp theo transcript đã đọc và audio thực tế đã kiểm tra: độ dài câu, từ vựng, cấu trúc và mật độ thông tin. Thứ tự ổn định; mức thử thách tương đối trong khóa, không quy đổi CEFR thành điểm thi.','Các bài bổ trợ kỹ năng nghe nền tảng, chưa thay thế giáo trình luyện thi đầy đủ.',1,TRUE,TRUE);
