INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('communication-basic','COMMUNICATION','Cơ bản','Nghe thông tin quen thuộc trong câu ngắn','Chọn nhóm bài rồi nghe và chép lại từng câu. Một bài dùng chung lịch sử ở mọi khóa.','Xếp theo transcript đã đọc và audio thực tế đã kiểm tra: độ dài câu, từ vựng, cấu trúc và mật độ thông tin. Thứ tự ổn định; mức thử thách tương đối trong khóa, không quy đổi CEFR thành điểm thi.','Luyện nghe và chép chính tả trong các tình huống đã kiểm tra; không bổ sung bài nói.',1,TRUE,TRUE);
